// swift-tools-version: 6.2

// Swift wrapper around the Rust engine (mfcore).
//
// Both the xcframework and Sources/MusicFetchCore/MusicFetchCore.swift are generated by
// scripts/build-core-apple.sh; run it before resolving this package.

import PackageDescription

let package = Package(
    name: "MusicFetchCore",
    platforms: [.macOS(.v26)],
    products: [
        .library(name: "MusicFetchCore", targets: ["MusicFetchCore"])
    ],
    targets: [
        .binaryTarget(name: "MfCoreFFI", path: "MfCoreFFI.xcframework"),
        .target(
            name: "MusicFetchCore",
            dependencies: ["MfCoreFFI"],
            swiftSettings: [
                // UniFFI 0.32.2 bindings are not Swift 6 clean (async foreign traits,
                // Sendable gaps) and break under default MainActor isolation, so this
                // target stays in Swift 5 mode and nonisolated.
                .swiftLanguageMode(.v5),
                .defaultIsolation(nil),
            ],
            // Mirrors rustc's native-static-libs; the module map also autolinks them.
            linkerSettings: [
                .linkedFramework("CoreFoundation"),
                .linkedFramework("Security"),
                .linkedFramework("SystemConfiguration"),
                .linkedLibrary("iconv"),
            ]
        ),
    ]
)
